script:
class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = { dark: this._themeFromProps(), plan: 'week', dogs: 2, fb: '', zip: '', zipChecked: false, area: '', menu: false, showBar: false, routeP: 1, vsPaused: false, vsPhase: 0, vsMin: 600, vsPiles: 0, vsT10: 0 };
  }
  componentDidMount() {
    this._onScroll = () => {
      const el = document.documentElement;
      const vh = window.innerHeight || 800;
      const canScroll = el.scrollHeight > vh + 120;
      const y = window.pageYOffset || el.scrollTop || 0;
      const show = !canScroll || y > 560;
      const next = {};
      if (show !== this.state.showBar) next.showBar = show;
      const r = document.getElementById('route');
      if (r) {
        const b = r.getBoundingClientRect();
        let p = (vh * 0.6 - b.top) / Math.max(1, b.height);
        p = Math.max(0, Math.min(1, p));
        if (Math.abs(p - this.state.routeP) > 0.01 || ((p === 0 || p === 1) && p !== this.state.routeP)) next.routeP = p;
      }
      if (Object.keys(next).length) this.setState(next);
    };
    window.addEventListener('scroll', this._onScroll, { passive: true });
    window.addEventListener('resize', this._onScroll);
    this._onScroll();
    this._themeInit();
    this._vsInit();
  }
  componentWillUnmount() {
    window.removeEventListener('scroll', this._onScroll);
    window.removeEventListener('resize', this._onScroll);
    this._themeStop();
    this._vsStop();
  }
  _themeFromProps() {
    const pt = this.props.theme || 'light';
    if (pt === 'dark') return true;
    if (pt === 'auto' && typeof window !== 'undefined' && window.matchMedia) return window.matchMedia('(prefers-color-scheme: dark)').matches;
    return false;
  }
  _themeInit() {
    if (typeof window === 'undefined' || !window.matchMedia) return;
    this._mq = window.matchMedia('(prefers-color-scheme: dark)');
    this._mqf = () => { if ((this.props.theme || 'light') === 'auto') this.setState({ dark: this._mq.matches }); };
    if (this._mq.addEventListener) this._mq.addEventListener('change', this._mqf);
  }
  _themeStop() {
    if (this._mq && this._mq.removeEventListener) this._mq.removeEventListener('change', this._mqf);
  }
  componentDidUpdate(prev) {
    if (prev.theme !== this.props.theme) this.setState({ dark: this._themeFromProps() });
  }
  _themeVals() {
    const d = !!this.state.dark;
    return {
      themeClass: d ? 'dark' : 'light',
      isDark: d,
      isLight: !d,
      themeLabel: d ? 'Switch to the light look' : 'Switch to the dark look',
      themeMenuLabel: d ? 'Light look' : 'Dark look',
      toggleTheme: () => this.setState({ dark: !this.state.dark })
    };
  }
  _vsInit() {
    this._vsAcc = 0;
    this._vsStart = Date.now();
    this._vsTimer = setInterval(() => this._vsUpdate(), 200);
    if (typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      this._vsSeek(9);
      this._vsAcc = 9000;
      this.setState({ vsPaused: true });
    }
  }
  _vsStop() { clearInterval(this._vsTimer); }
  _vsDerive(t) {
    const pT = [6.92, 7.98, 8.93, 9.99, 11.13, 12.19, 13.37, 14.28];
    const pC = [2, 4, 6, 8, 10, 11, 13, 14];
    let piles = 0;
    for (let i = 0; i < pT.length; i++) { if (t >= pT[i]) piles = pC[i]; }
    const ends = [3.4, 5.8, 14.8, 17.8, 20.2];
    let phase = 0;
    while (phase < 5 && t >= ends[phase]) phase++;
    const sim = 36019 + t * 58.714;
    return { phase: phase, min: Math.floor(sim / 60), piles: piles };
  }
  _vsNow() {
    const run = this.state.vsPaused ? 0 : Date.now() - this._vsStart;
    return ((this._vsAcc + run) / 1000) % 24;
  }
  _vsUpdate() {
    const s = this.state;
    if (s.vsPaused) return;
    const t = this._vsNow();
    const v = this._vsDerive(t);
    const t10 = Math.floor(t * 10);
    if (t10 !== s.vsT10 || v.phase !== s.vsPhase || v.min !== s.vsMin || v.piles !== s.vsPiles) this.setState({ vsT10: t10, vsPhase: v.phase, vsMin: v.min, vsPiles: v.piles });
  }
  _vsSeek(t) {
    this._vsAcc = t * 1000;
    this._vsStart = Date.now();
    const el = typeof document !== 'undefined' ? document.querySelector('.vs') : null;
    if (el && el.getAnimations) {
      el.getAnimations({ subtree: true }).forEach((a) => { try { a.currentTime = t * 1000; } catch (err) { } });
    }
    const v = this._vsDerive(t);
    this.setState({ vsT10: Math.floor(t * 10), vsPhase: v.phase, vsMin: v.min, vsPiles: v.piles });
  }
  _vsToggle() {
    if (this.state.vsPaused) {
      this._vsStart = Date.now();
      this.setState({ vsPaused: false });
    } else {
      this._vsAcc += Date.now() - this._vsStart;
      this.setState({ vsPaused: true });
    }
  }
  _vsVals() {
    const s = this.state;
    const caps = [
      'We pull up. We texted you when we were close.',
      'Your scooper walks to your gate.',
      'We shut the gate. Then we pick up every pile, front to back.',
      'We spray sanitizer where your dogs go most. It’s free!',
      'We latch the gate, pull on it, and take a photo.',
      'Your report goes to your phone. See you next week!'
    ];
    const h = Math.floor(s.vsMin / 60);
    const m = s.vsMin % 60;
    const h12 = h > 12 ? h - 12 : h;
    const clock = h12 + ':' + (m < 10 ? '0' : '') + m + (h >= 12 ? ' PM' : ' AM');
    return {
      vsClass: 'vs' + (s.vsPaused ? ' paused' : ''),
      vClock: clock,
      vPiles: s.vsPiles,
      vCaption: caps[s.vsPhase] || caps[0],
      vsRepOn: s.vsPhase >= 5,
      vsPlaying: !s.vsPaused,
      vsIsPaused: !!s.vsPaused,
      vsToggleLabel: s.vsPaused ? 'Play the visit' : 'Pause the visit',
      vsToggle: () => this._vsToggle(),
      vsT10: s.vsT10,
      vsValText: clock + ', ' + (caps[s.vsPhase] || caps[0]),
      vsScrub: (e) => { const t = Math.max(0, Math.min(23.9, Number(e.target.value) / 10)); this._vsSeek(t); }
    };
  }
  _price(id, dogs) {
    const base = { week: 108, twice: 189, eow: 75 };
    const extra = { week: 13, twice: 13, eow: 9 };
    return base[id] + Math.max(0, dogs - 2) * extra[id];
  }
  _per(id, dogs) {
    const visits = { week: 52 / 12, twice: 104 / 12, eow: 26 / 12 };
    return Math.round(this._price(id, dogs) / visits[id]);
  }
  _cal(id, onBand) {
    const out = [];
    for (let i = 0; i < 28; i++) {
      const d = i % 7;
      const w = Math.floor(i / 7);
      const on = id === 'week' ? d === 2 : id === 'twice' ? (d === 2 || d === 5) : (d === 2 && w % 2 === 0);
      out.push({ bg: on ? '#FF4A1C' : (onBand ? 'rgba(255,255,255,.16)' : 'var(--line)') });
    }
    return out;
  }
  _plans(onBand) {
    const s = this.state;
    const names = { week: 'Every week', twice: 'Twice a week', eow: 'Every other week' };
    return ['week', 'twice', 'eow'].map((id) => {
      const on = s.plan === id;
      return {
        id: id,
        name: names[id],
        price: '$' + this._price(id, s.dogs),
        per: 'About $' + this._per(id, s.dogs) + ' a visit',
        on: on,
        pick: () => this.setState({ plan: id }),
        aria: names[id] + ', $' + this._price(id, s.dogs) + ' a month',
        cal: this._cal(id, onBand),
        border: on ? '#FF4A1C' : (onBand ? 'rgba(255,255,255,.18)' : 'var(--field)'),
        bg: on ? 'rgba(255,74,28,.12)' : 'transparent',
        ring: on ? '#FF4A1C' : (onBand ? '#AEB5D8' : 'var(--mute)'),
        dot: on ? '#FF4A1C' : 'transparent'
      };
    });
  }
  _zipArea(zip) {
    return ({ '85396': 'verrado', '85355': 'citrus', '85395': 'goodyear', '85340': 'litchfield' })[zip] || '';
  }
  _checkZip() {
    this.setState({ zipChecked: true, area: this._zipArea(this.state.zip) });
  }
  _areaVals() {
    const s = this.state;
    const areas = {
      verrado: { name: 'Verrado', meta: 'VERRADO · BUCKEYE · 85396' },
      citrus: { name: 'Citrus Park', meta: 'CITRUS PARK · 85355' },
      goodyear: { name: 'Goodyear', meta: 'GOODYEAR · NORTH OF INTERSTATE 10 · 85395' },
      litchfield: { name: 'Litchfield Park', meta: 'LITCHFIELD PARK · 85340' }
    };
    const pin = (id) => {
      const on = s.area === id;
      return { on: on, bg: on ? 'var(--ink)' : 'var(--card)', fg: on ? 'var(--bg)' : 'var(--ink)', pick: () => this.setState({ area: id, zip: '', zipChecked: false }) };
    };
    const blob = (id) => (s.area === id ? (s.dark ? 'rgba(255,74,28,.58)' : 'rgba(255,74,28,.42)') : 'rgba(255,74,28,0)');
    const a = areas[s.area];
    const byZip = s.zipChecked && !!this._zipArea(s.zip);
    return {
      mV: pin('verrado'), mC: pin('citrus'), mG: pin('goodyear'), mL: pin('litchfield'),
      bV: blob('verrado'), bC: blob('citrus'), bG: blob('goodyear'), bL: blob('litchfield'),
      areaOn: !!a,
      areaName: byZip ? 'ZIP ' + s.zip : (a ? a.name : ''),
      areaMeta: a ? a.meta : '',
      zip: s.zip,
      onZip: (e) => this.setState({ zip: String(e.target.value || '').replace(/\D/g, '').slice(0, 5), zipChecked: false }),
      zipKey: (e) => { if (e.key === 'Enter') this._checkZip(); },
      checkZip: () => this._checkZip(),
      zipNo: s.zipChecked && s.zip.length === 5 && !this._zipArea(s.zip),
      zipShort: s.zipChecked && s.zip.length < 5
    };
  }
  renderVals() {
    const s = this.state;
    const names = { week: 'Every week', twice: 'Twice a week', eow: 'Every other week' };
    const total = this._price(s.plan, s.dogs);
    const dogs = s.dogs === 1 ? '1 dog' : s.dogs + ' dogs';
    const furs = ['#D9A066', '#6B4A34', '#F1E3C8', '#3A3434', '#B5652A', '#9A9A9A'];
    const lbs = Math.round(s.dogs * 274 / 10) * 10;
    const good = s.fb === 'good';
    const off = s.fb === 'off';
    const lit = (i) => (s.routeP >= i / 6 ? '#FF4A1C' : 'var(--bg2)');
    return Object.assign({}, this._themeVals(), this._vsVals(), this._areaVals(), {
      r0: lit(0), r1: lit(1), r2: lit(2), r3: lit(3), r4: lit(4), r5: lit(5),
      routeTop: 'calc(10px + (100% - 20px) * ' + s.routeP.toFixed(3) + ')',
      plans: this._plans(true),
      dogList: furs.slice(0, s.dogs).map((f) => ({ fur: f })),
      dogLabel: dogs,
      poopLine: (s.dogs === 1 ? '1 dog makes' : s.dogs + ' dogs make') + ' about ' + lbs + ' pounds of poop a year. We pick up all of it.',
      dogDown: () => this.setState({ dogs: Math.max(1, s.dogs - 1) }),
      dogUp: () => this.setState({ dogs: Math.min(6, s.dogs + 1) }),
      planLine: names[s.plan] + ' · ' + dogs,
      totalLabel: '$' + total,
      perLine: 'About $' + this._per(s.plan, s.dogs) + ' a visit',
      ctaLabel: 'Book at $' + total + ' a month',
      fbGood: () => this.setState({ fb: 'good' }),
      fbOff: () => this.setState({ fb: 'off' }),
      fbIsGood: good,
      fbIsOff: off,
      fbGoodBorder: good ? 'var(--ok)' : 'var(--field)',
      fbGoodBg: good ? 'var(--ok)' : 'transparent',
      fbGoodFg: good ? '#FFFFFF' : 'var(--ink)',
      fbOffBorder: off ? 'var(--ink)' : 'var(--field)',
      fbOffBg: off ? 'var(--ink)' : 'transparent',
      fbOffFg: off ? 'var(--bg)' : 'var(--ink)',
      fbText: good ? 'Thanks! See you next week.' : off ? 'Free return booked. We will be back within 24 hours.' : 'Tap “Something’s off” and we come back for free within 24 hours.',
      showBar: s.showBar,
      menu: s.menu,
      openMenu: () => this.setState({ menu: true }),
      closeMenu: () => this.setState({ menu: false })
    });
  }
}
